const uid=(n:number)=>`00000000-0000-4000-8000-${String(n).padStart(12,'0')}`,origin='https://shop.test',literal='চাল\0'+String.fromCharCode(0xd800);
let db:PGlite,source:SetupCommand,branch:SetupCommand,foreign:SetupCommand,supplier:Supplier,branchSupplier:Supplier,stock:StockItem,branchStock:StockItem,branchPurchase:Purchase,lastError='';
const actors:{n:number;id:string;role:string;outlet:string}[]=[],initial:CloudRecord[]=[];
async function insert(records:CloudRecord[]){await db.transaction(async sql=>{for(const r of records){const keys=Object.keys(r.values);await sql.query(`insert into public.${r.table}(${keys.join(',')}) values(${keys.map((_,i)=>'$'+(i+1)).join(',')})`,Object.values(r.values));}});}
async function asRole<T>(n:number|null,role:'authenticated'|'service_role'|'anon',query:string,args:unknown[]=[]){return db.transaction(async sql=>{await sql.exec('set local role '+role);await sql.query("select set_config('request.jwt.claims',$1,true)",[JSON.stringify({role,...(n?{sub:uid(n)}:{}),user_metadata:{role:'owner'}})]);return (await sql.query<T>(query,args)).rows;});}
function store(beforeFinish?:(args:Record<string,unknown>)=>Promise<void>){return createCommandStore('https://database.test','sb_publishable_test_only',async(url,options)=>{
 const name=new URL(String(url)).pathname.split('/').at(-1)!,args=JSON.parse(options?.body as string),headers=new Headers(options?.headers),service=headers.get('apikey')==='sb_secret_test_only';
 const parameters:Record<string,string[]>={admit_purchase_record:['p_outlet_id'],prepare_purchase_write:['p_id','p_ticket_id','p_type','p_outlet_id','p_plan','p_hash','p_occurred_at'],finish_purchase_write:['p_ticket_id','p_token','p_records']};
 expect(parameters[name]).toBeDefined();if(service){expect(headers.has('Authorization')).toBe(false);await beforeFinish?.(args);}else expect(headers.get('apikey')).toBe('sb_publishable_test_only');
 try{const r=await asRole<{data:unknown}>(service?null:Number(headers.get('Authorization')!.split('.')[1]),service?'service_role':'authenticated',`select public.${name}(${parameters[name].map((_,i)=>'$'+(i+1)).join(',')}) data`,parameters[name].map(k=>['p_plan','p_records'].includes(k)?JSON.stringify(args[k]):args[k]));return new Response(JSON.stringify(r[0].data));}
 catch(error){const {code,message,detail:details}=error as {code:string;message:string;detail?:string};lastError=code+': '+message;return new Response(JSON.stringify({code,details}),{status:code==='42501'?403:['PT409','23505'].includes(code)?409:code==='PT429'?429:['22023','23514'].includes(code)?400:500});}
 },{serviceKey:'sb_secret_test_only'});}
function request(c:unknown,header?:string){return new Request('https://api.test/commands',{method:'POST',headers:{Origin:origin,Authorization:'Bearer user.1.signature','Content-Type':'application/json',...(header?{[purchaseBodyHeader]:header}:{})},body:JSON.stringify(c)});}
async function http(n:number,c:unknown,beforeFinish?:(args:Record<string,unknown>)=>Promise<void>,header?:string|null,currency:string|null='BDT'){const value=c as PurchaseCommand,req=request(c,header===null?undefined:header??(value.type==='purchase.record'?value.outletId:undefined));req.headers.set('Authorization',`Bearer user.${n}.signature`);if(currency!==null&&['purchase.record','purchase.undo'].includes(value.type))req.headers.set(savedCurrencyHeader,currency);return createCommandsHandler({origins:new Set([origin]),store:store(beforeFinish)})(req);}
const base=()=>({id:newInboxId(),outletId:source.snapshot.outlet.id,occurredAt:Date.now()-1000});
const profile=()=>({name:literal,phone:'০১৭১২৩৪৫৪৮৩',note:literal});
const createSupplier=():Extract<PurchaseCommand,{type:'supplier.create'}>=>({...base(),type:'supplier.create',supplierId:newInboxId(),input:profile()});
const editSupplier=(s=supplier):Extract<PurchaseCommand,{type:'supplier.update'}>=>({...base(),type:'supplier.update',supplierId:s.id,revision:s.revision,input:{...profile(),name:'Updated '+literal}});
const statusSupplier=(s=supplier,restore=false):Extract<PurchaseCommand,{type:'supplier.archive'|'supplier.restore'}>=>({...base(),type:restore?'supplier.restore':'supplier.archive',supplierId:s.id,revision:s.revision});
const invoiceInput=():PurchaseRecordInput=>({supplierId:supplier.id,supplierName:'Ignored when a saved supplier is selected',reference:literal,lines:[{stockItemId:stock.id,name:literal,unit:'kg',qty:2.5,unitPrice:12001}],paid:'due',wallet:null,note:literal});
const record=():Extract<PurchaseCommand,{type:'purchase.record'}>=>({...base(),type:'purchase.record',purchaseId:newInboxId(),input:invoiceInput()});
const undo=(id:string):Extract<PurchaseCommand,{type:'purchase.undo'}>=>({...base(),type:'purchase.undo',purchaseId:id});
async function accepted(c:PurchaseCommand,n=1){const r=await http(n,c);expect(r.status,lastError+' '+await r.clone().text()).toBe(200);return parsePurchaseCommandReceipt(await r.json(),c);}
it('does not reinterpret an original BDT invoice as USD after the current shop profile changes',async()=>{
 const c=record(),original=JSON.stringify(c),before=await counts();
 try{
  await db.query("update public.outlets set currency='USD' where id=$1",[c.outletId]);
  await expect(store().apply('user.1.signature',c,'BDT')).rejects.toThrow();
  expect(await counts()).toEqual(before);expect(JSON.stringify(c)).toBe(original);
 }finally{await db.query("update public.outlets set currency='BDT' where id=$1",[c.outletId]);}
});
it('new invoices require their original unit, while a genuine completed invoice is recoverable without it',async()=>{
 const c=record(),before=await counts();
 expect((await http(1,c,undefined,undefined,null)).status).toBe(409);
 expect((await http(1,c,undefined,undefined,'USD')).status).toBe(409);
 expect((await http(1,c,undefined,undefined,'bdt')).status).toBe(400);
 expect(await counts()).toEqual(before);
 const receipt=await accepted(c);
 try{
  await db.query("update public.outlets set currency='USD' where id=$1",[c.outletId]);
  const replay=await http(1,c,undefined,undefined,null);expect(replay.status).toBe(200);expect(await replay.json()).toEqual(receipt);
  expect((await counts()).purchases).toBe(before.purchases+1);
 }finally{await db.query("update public.outlets set currency='BDT' where id=$1",[c.outletId]);}
});
it('historical invoice undo keeps BDT after a USD profile change, with one actual audit and receipt',async()=>{
 const c=record();await accepted(c);const command=undo(c.purchaseId),original=JSON.stringify(command);
 try{
  await db.query("update public.outlets set currency='USD' where id=$1",[c.outletId]);
  const before=await counts();expect((await http(1,command,undefined,undefined,'USD')).status).toBe(409);expect(await counts()).toEqual(before);
  const receipt=await accepted(command);expect(await accepted(command)).toEqual(receipt);
  expect(await savedPurchase(c.purchaseId)).toMatchObject({currency:'BDT',voidedAt:command.occurredAt});
  expect((await counts()).receipts).toBe(before.receipts+1);expect((await counts()).events).toBe(before.events+1);expect(JSON.stringify(command)).toBe(original);
 }finally{await db.query("update public.outlets set currency='BDT' where id=$1",[c.outletId]);}
});
it('a profile race after invoice formatting rechecks the original unit on SQL retry before any financial commit',async()=>{
 const c=record(),before=await counts();let finishes=0;
 try{
  const response=await http(1,c,async()=>{finishes++;await db.query("update public.outlets set currency='USD' where id=$1",[c.outletId]);});
  expect(response.status).toBe(409);expect(finishes).toBe(1);expect(await counts()).toEqual(before);
 }finally{await db.query("update public.outlets set currency='BDT' where id=$1",[c.outletId]);}
});
async function savedSupplier(id=supplier.id){return decodeCommandRecord('suppliers',JSON.parse((await db.query<{data:string}>('select row_to_json(s)::text data from public.suppliers s where id=$1',[id])).rows[0].data)) as unknown as Supplier;}
async function savedPurchase(id:string){return decodeCommandRecord('purchases',JSON.parse((await db.query<{data:string}>('select row_to_json(p)::text data from public.purchases p where id=$1',[id])).rows[0].data)) as unknown as Purchase;}
async function counts(){return (await db.query<{suppliers:number;purchases:number;stock:number;moves:number;entries:number;sales:number;events:number;receipts:number}>("select (select count(*)::int from public.suppliers) suppliers,(select count(*)::int from public.purchases) purchases,(select count(*)::int from public.stock_items) stock,(select count(*)::int from public.stock_moves) moves,(select count(*)::int from public.credit_entries) entries,(select count(*)::int from public.sales) sales,(select count(*)::int from public.events) events,(select count(*)::int from private.shop_command_receipts) receipts")).rows[0];}
async function prepare(c:PurchaseCommand,n=1){return (await asRole<{data:Record<string,unknown>}>(n,'authenticated','select public.prepare_purchase_write($1,$2,$3,$4,$5,$6,$7) data',[c.id,newInboxId(),c.type,c.outletId,JSON.stringify(purchaseWritePlan(c)),await purchaseFingerprint(c),c.occurredAt]))[0].data;}
async function finish(p:Record<string,unknown>,c:PurchaseCommand,modify?:(records:CloudRecord[])=>void){const f=purchaseWriteFields(p,c,p.ticketId as string);modify?.(f.p_records as CloudRecord[]);return asRole<{data:unknown}>(null,'service_role','select public.finish_purchase_write($1,$2,$3) data',[f.p_ticket_id,f.p_token,JSON.stringify(f.p_records)]);}
beforeAll(async()=>{
 db=await PGlite.create();for(const f of ['supabase-auth.sql','supabase-storage.sql'])await db.exec(readFileSync(new URL('./fixtures/'+f,import.meta.url),'utf8'));
 const dir=new URL('../supabase/migrations/',import.meta.url);for(const f of readdirSync(dir).filter(f=>f.endsWith('.sql')).sort())await db.exec(readFileSync(new URL(f,dir),'utf8'));
 for(const n of [1,2,3,4,5,6])await db.query('insert into auth.users(id,phone,phone_confirmed_at) values($1,$2,now())',[uid(n),'1415555010'+n]);
 const cfg={businessType:'corner_shop' as const,marketCode:'BD' as const,name:'Purchases',phone:'01712345482'};source=setupCommand(cfg);branch=setupCommand({...cfg,name:'Branch'});foreign=setupCommand({...cfg,name:'Foreign'});branch.snapshot.business=source.snapshot.business;branch.snapshot.outlet.businessId=source.snapshot.business.id;branch.snapshot.owner={...source.snapshot.owner,outletIds:[branch.snapshot.outlet.id]};
 for(const [s,n,skip] of [[source,1,false],[branch,1,true],[foreign,4,false]] as const){const tables=emptyBackupTables();tables.businesses.push(s.snapshot.business);tables.outlets.push(s.snapshot.outlet);tables.members.push(s.snapshot.owner);const plan=await prepareCloudMigration(createBackup(tables),uid(n));await insert(plan.records.filter(r=>!(skip&&['businesses','members','member_outlets'].includes(r.table))));}
 actors.push({n:1,id:source.snapshot.owner.id,role:'owner',outlet:source.snapshot.outlet.id},{n:4,id:foreign.snapshot.owner.id,role:'owner',outlet:foreign.snapshot.outlet.id});
 for(const [n,role,outlet] of [[2,'manager',source.snapshot.outlet.id],[3,'manager',branch.snapshot.outlet.id],[5,'staff',source.snapshot.outlet.id],[6,'agent',source.snapshot.outlet.id]] as const){const id=newInboxId();await db.query('insert into public.members(id,business_id,auth_user_id,name,role,created_at,updated_at) values($1,$2,$3,$4,$5,1,1)',[id,source.snapshot.business.id,uid(n),'"Person"',role]);actors.push({n,id,role,outlet});}
 const at=Date.now()-1000;
 for(const [snap,isBranch] of [[source.snapshot,false],[branch.snapshot,true]] as const){const s=saveSupplierCommand({name:'Supplier '+literal,phone:'01712345483',note:literal},snap,null,0,at);if(isBranch)branchSupplier=s.supplier;else supplier=s.supplier;initial.push(encodeCommandRecord('suppliers',s.supplier,snap.business.id),encodeCommandRecord('events',s.event,snap.business.id));
  const ctx:StockContext={setup:snap,items:[],moves:[],suppliers:[s.supplier]},st=saveStockItemCommand({name:'Rice '+literal,unit:'kg',onHand:20,target:30,packSize:1,supplierId:s.supplier.id},ctx,null,0,at);if(isBranch)branchStock=st.items[0];else stock=st.items[0];initial.push(...st.items.map(x=>encodeCommandRecord('stockItems',x,snap.business.id)),...st.moves.map(x=>encodeCommandRecord('stockMoves',x,snap.business.id)),...st.events.map(x=>encodeCommandRecord('events',x,snap.business.id)));
  if(isBranch){const p=recordPurchaseCommand({supplierId:s.supplier.id,supplierName:'',reference:'Branch only',lines:[{name:'Rice',unit:'kg',qty:1,unitPrice:100}],paid:'due',note:literal},snap,[s.supplier],st.items,at);branchPurchase=p.purchase;initial.push(encodeCommandRecord('purchases',p.purchase,snap.business.id),encodeCommandRecord('events',p.event,snap.business.id));}
 }
},30_000);
beforeEach(async()=>{lastError='';await db.exec("delete from private.purchase_review_tickets;delete from private.purchase_command_resolutions;truncate public.suppliers,public.stock_items,public.events cascade;delete from private.purchase_write_tickets;update auth.users set phone='1415555010'||right(id::text,1),phone_confirmed_at=now(),banned_until=null,deleted_at=null;update public.members set active=true");await db.query("update public.outlets set currency='BDT',timezone='Asia/Dhaka' where id=$1",[source.snapshot.outlet.id]);for(const a of actors){await db.query('update public.members set role=$1,auth_user_id=$2 where id=$3',[a.role,uid(a.n),a.id]);await db.query('delete from public.member_outlets where member_id=$1',[a.id]);await db.query('insert into public.member_outlets values($1,$2,$3)',[a.n===4?foreign.snapshot.business.id:source.snapshot.business.id,a.id,a.outlet]);}await insert(initial);});
afterAll(async()=>{await db?.close();});
it('last admitted supplier fields win despite older device time and retain the losing values and monotonic update time',async()=>{
 const first=editSupplier(),second=editSupplier();first.occurredAt=Date.now()+240000;first.input.name='First admitted';second.occurredAt=Date.now()-5000;second.input.name='Last admitted';const original=JSON.stringify(second);const a=await accepted(first),b=await accepted(second,2),current=await savedSupplier();expect(current).toMatchObject({name:second.input.name,revision:supplier.revision+2,updatedAt:a.updatedAt});expect(b.updatedAt).toBe(a.updatedAt);expect(b.at).toBeGreaterThanOrEqual(a.at);expect(JSON.stringify(second)).toBe(original);const event=decodeCommandRecord('events',JSON.parse((await db.query<{data:string}>('select row_to_json(e)::text data from public.events e where id=$1',[second.id])).rows[0].data)) as unknown as {before:Supplier;after:Supplier};expect(event.before.name).toBe(first.input.name);expect(event.after.name).toBe(second.input.name);expect(await accepted(second,2)).toEqual(b);
});
it('concurrent archive and restore assertions are idempotent and metadata edits preserve the current archive state',async()=>{
 const archive=statusSupplier(),first=await accepted(archive),archived=await savedSupplier(),again={...archive,id:newInboxId(),occurredAt:archive.occurredAt-1};expect((await accepted(again,2)).revision).toBe((first.revision as number)+1);expect((await savedSupplier()).archivedAt).toBe(archived.archivedAt);await accepted(editSupplier());expect((await savedSupplier()).archivedAt).toBe(archived.archivedAt);const restore=statusSupplier(archived,true);await accepted(restore);await accepted({...restore,id:newInboxId()},2);expect(await savedSupplier()).toMatchObject({revision:supplier.revision+5,createdAt:supplier.createdAt});expect((await savedSupplier()).archivedAt).toBeUndefined();
});
it('unobserved future supplier revisions cannot change fields or archive state',async()=>{
 const before=await counts(),c=editSupplier({...supplier,revision:supplier.revision+1});expect((await http(1,c)).status).toBe(409);expect((await http(1,statusSupplier({...supplier,revision:supplier.revision+1}))).status).toBe(409);expect(await counts()).toEqual(before);
});
it.each([1,2])('operator %s saves a supplier with original IDs, physical time, Bengali phone and literal text',async n=>{const c=createSupplier(),r=await accepted(c,n),saved=await savedSupplier(c.supplierId);expect(saved).toMatchObject({id:c.supplierId,name:literal,phone:'+8801712345483',note:literal,revision:1,eventId:c.id,createdAt:c.occurredAt,updatedAt:r.updatedAt});});
it('supplier sets use the current revision and preserve creation, archive state and every audit',async()=>{const c=editSupplier();await accepted(c);expect(await accepted({...c,id:newInboxId()})).toMatchObject({revision:3});const updated=await savedSupplier();await accepted(statusSupplier(updated));const archived=await savedSupplier();expect(archived.archivedAt).toBeDefined();await accepted(editSupplier(archived));expect((await savedSupplier()).archivedAt).toBe(archived.archivedAt);await accepted(statusSupplier(await savedSupplier(),true));expect(await savedSupplier()).toMatchObject({createdAt:supplier.createdAt,revision:6});expect((await savedSupplier()).archivedAt).toBeUndefined();});
it.each(['cash','wallet','card','due'] as const)('%s invoices use exact line rounding without changing stock, sales or customer debt',async paid=>{const c=record();c.input.paid=paid;c.input.wallet=paid==='wallet'?'bKash':null;const before=await counts(),r=await accepted(c),p=await savedPurchase(c.purchaseId),after=await counts();expect(p).toMatchObject({id:c.purchaseId,total:30003,supplierName:supplier.name,createdAt:c.occurredAt,updatedAt:r.updatedAt,eventId:c.id,currency:'BDT',createdBy:source.snapshot.owner.id});expect(p.lines[0]).toMatchObject({qty:2.5,lineTotal:30003});for(const key of ['stock','moves','sales','entries'] as const)expect(after[key]).toBe(before[key]);expect(after.purchases).toBe(before.purchases+1);});
it('manual suppliers, duplicate selected stock lines and zero-priced invoices remain valid',async()=>{const c=record();c.input.supplierId=null;c.input.supplierName=literal;c.input.lines.push({...c.input.lines[0],qty:0.001,unitPrice:0});c.input.lines[0].unitPrice=0;expect(purchaseWritePlan(c).stockItemIds).toEqual([stock.id]);await accepted(c);expect(await savedPurchase(c.purchaseId)).toMatchObject({total:0,supplierName:literal});});
it('the immutable original receipt replays after later supplier edits, archival and invoice undo',async()=>{const c=record(),first=await accepted(c);await accepted(editSupplier());await accepted(statusSupplier(await savedSupplier()));const u=undo(c.purchaseId);await accepted(u);expect(await accepted(c)).toEqual(first);expect(await accepted(u)).toMatchObject({undoOf:c.purchaseId});expect((await http(2,c)).status).toBe(403);expect((await http(1,{...c,input:{...c.input,note:'different'}})).status).toBe(409);});
it('undo preserves the entire original invoice and reverses only once with a separate audit',async()=>{const c=record();await accepted(c);const before=await savedPurchase(c.purchaseId),u=undo(c.purchaseId),r=await accepted(u),after=await savedPurchase(c.purchaseId);expect(after).toEqual({...before,voidedAt:u.occurredAt,updatedAt:r.updatedAt});expect((await http(1,undo(c.purchaseId))).status).toBe(400);});
it('the complete 200-line escaped invoice passes authenticated body admission and the normal limit still rejects it',async()=>{const c=record();c.input.lines=Array.from({length:200},()=>({stockItemId:stock.id,name:'\0'.repeat(120),unit:'kg',qty:2.5,unitPrice:12001}));c.input.note='\0'.repeat(4000);expect(JSON.stringify(c).length).toBeGreaterThan(32000);expect((await http(1,c,undefined,null)).status).toBe(413);const r=await accepted(c);expect(r.total).toBe(6_000_600);expect((await savedPurchase(c.purchaseId)).lines).toHaveLength(200);await accepted(undo(c.purchaseId));expect((await savedPurchase(c.purchaseId)).voidedAt).toBeDefined();},30_000);
it.each([3,4,5,6])('identity %s cannot write suppliers, record invoices or admit larger bodies',async n=>{expect((await http(n,createSupplier())).status).toBe(403);expect((await http(n,record())).status).toBe(403);});
it('foreign supplier, stock and invoice IDs never enter a prepared context',async()=>{const s=editSupplier(branchSupplier),p=record();await expect(prepare(s)).rejects.toMatchObject({code:'42501'});p.input.supplierId=branchSupplier.id;expect((await http(1,p)).status).toBe(403);p.input.supplierId=supplier.id;p.input.lines[0].stockItemId=branchStock.id;expect((await http(1,p)).status).toBe(403);expect((await http(1,undo(branchPurchase.id))).status).toBe(403);});
it.each(['inactive','role','unconfirmed','phone','banned','deleted','assignment','identity'])('live %s revocation is checked at service-only invoice completion',async kind=>{const actor=actors.find(a=>a.n===2)!;const r=await http(2,record(),async()=>{if(kind==='assignment')await db.query('delete from public.member_outlets where member_id=$1',[actor.id]);else if(kind==='identity')await db.query('update public.members set auth_user_id=null where id=$1',[actor.id]);else if(kind==='inactive')await db.query('update public.members set active=false where id=$1',[actor.id]);else if(kind==='role')await db.query("update public.members set role='staff' where id=$1",[actor.id]);else await db.query(`update auth.users set ${kind==='unconfirmed'?'phone_confirmed_at=null':kind==='phone'?"phone=''":kind==='banned'?"banned_until=now()+interval '1 day'":'deleted_at=now()'} where id=$1`,[uid(2)]);});expect(r.status,lastError).toBe(403);expect((await counts()).purchases).toBe(1);});
it('an in-flight invoice rechecks a changed supplier and records its latest saved name with original device IDs',async()=>{const c=record();let calls=0;expect((await http(1,c,async()=>{if(++calls===1)await accepted(editSupplier());})).status).toBe(200);expect(calls).toBe(2);expect(await savedPurchase(c.purchaseId)).toMatchObject({supplierName:'Updated '+literal,eventId:c.id,id:c.purchaseId});});
it('a newly archived supplier or stock item rejects a refreshed invoice without a partial write',async()=>{const c=record();let calls=0;const r=await http(1,c,async()=>{if(++calls===1)await accepted(statusSupplier());});expect(r.status).toBe(400);expect((await counts()).purchases).toBe(1);});
