 expect((await invoiceReviewHttp({...packet,token:view.token,outcome:'replaced'},true)).status).toBe(409);expect(await counts()).toEqual(before);
 const result=await invoiceReviewHttp({...packet,token:view.token,outcome:'withdrawn'},true);expect(result.status,lastError+' '+await result.clone().text()).toBe(200);const receipt=parsePurchaseResolutionReceipt(await result.json(),c);expect(receipt.outcome).toBe('withdrawn');expect(await counts()).toEqual({...before,events:before.events+1,receipts:before.receipts+1});expect(JSON.stringify(packet)).toBe(original);
