it('an auxiliary resolution audit failure rolls the invoice and replacement receipt back together',async()=>{
 const packet=await invoicePacket(record()),r=await openInvoiceReview(packet),replacement=reviewedPurchaseProposal(packet.command,packet.replacementId),p=await prepare(replacement),before=await counts();await db.exec("create function public.reject_invoice_resolution() returns trigger language plpgsql as $$begin if new.command='sync.resolve' then raise exception 'synthetic resolution audit failure';end if;return new;end$$;create trigger reject_invoice_resolution before insert on public.events for each row execute function public.reject_invoice_resolution()");try{await expect(finishInvoiceReview(r,'replaced',p,replacement)).rejects.toBeDefined();expect(await counts()).toEqual(before);}finally{await db.exec('drop trigger reject_invoice_resolution on public.events;drop function public.reject_invoice_resolution()');}
});
it('a genuine ordinary invoice outcome wins before imposing a later profile or another review decision',async()=>{
 const c=record(),packet=await invoicePacket(c),r=await openInvoiceReview(packet),receipt=await accepted(c);await db.query("update public.outlets set currency='USD' where id=$1",[c.outletId]);const before=await counts();expect(await finishInvoiceReview(r)).toEqual(receipt);expect(await (await invoiceReviewHttp(packet)).json()).toEqual({done:true,receipt});expect(await counts()).toEqual(before);
});
it('a lost HTTP replacement reply recovers the genuine source-bound result without another invoice',async()=>{
 const packet=await invoicePacket(record()),read=await invoiceReviewHttp(packet),view=(await read.json()).review,decision={...packet,token:view.token,outcome:'replaced'},lost=await invoiceReviewHttp(decision,true,{returned:(name,value)=>{if(name==='finish_purchase_review')throw Error('Connection closed after SQL commit');return value;}});expect(lost.status).toBe(503);const before=await counts(),recovered=await invoiceReviewHttp(packet);expect(recovered.status,lastError+' '+await recovered.clone().text()).toBe(200);expect(await recovered.json()).toMatchObject({done:true,receipt:{type:'command.resolved',outcome:'replaced',sourceHash:packet.sourceHash}});expect(await counts()).toEqual(before);expect((await invoiceReviewHttp({...packet,sourceHash:'b'.repeat(64)})).status).toBe(409);
});
it('invoice review storage is private and forced-RLS, and ordinary callers cannot finalize it',async()=>{
 const packet=await invoicePacket(record()),r=await openInvoiceReview(packet);for(const role of ['anon','authenticated','service_role'] as const)for(const table of ['purchase_review_tickets','purchase_command_resolutions'])await expect(asRole(role==='authenticated'?1:null,role,'select * from private.'+table)).rejects.toMatchObject({code:'42501'});await expect(asRole(1,'authenticated','select public.finish_purchase_review($1,$2,$3,$4,$5,$6,$7)',[r.id,r.token,'withdrawn',null,null,null,null])).rejects.toMatchObject({code:'42501'});const rows=(await db.query<{relrowsecurity:boolean;relforcerowsecurity:boolean}>("select relrowsecurity,relforcerowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and relname in ('purchase_review_tickets','purchase_command_resolutions')")).rows;expect(rows).toEqual([{relrowsecurity:true,relforcerowsecurity:true},{relrowsecurity:true,relforcerowsecurity:true}]);
});
it('the HTTP comparison rejects a changed occurrence or saved-unit binding before any decision',async()=>{
 for(const patch of [{occurredAt:0},{savedCurrency:'USD'}]){const packet=await invoicePacket(record()),before=await counts(),read=await invoiceReviewHttp(packet,false,{returned:(name,value)=>name==='prepare_purchase_review'?{...(value as object),...patch}:value});expect(read.status).toBe(503);expect(await counts()).toEqual(before);}
});
